using Microsoft.EntityFrameworkCore;using POS.Application.Abstractions;using POS.Application.Common;using POS.Domain.Entities;
namespace POS.Application.RestaurantInventory;
public record StockCountLineDto(Guid IngredientId,string Name,decimal SystemQuantity,decimal CountedQuantity,decimal VarianceQuantity);public record StockCountDto(Guid Id,Guid BranchId,Guid WarehouseId,DateTime CreatedAt,string Status,List<StockCountLineDto> Lines);public record CountLineInput(Guid IngredientId,decimal CountedQuantity);
public class StockCountService(IAppDbContext db,ICurrentUserService user){public async Task<StockCountDto>Start(Guid branchId,Guid warehouseId,CancellationToken ct){if(!await db.Warehouses.AnyAsync(x=>x.Id==warehouseId&&x.BranchId==branchId&&x.IsActive,ct))throw new ValidationException("Warehouse unavailable.");var stocks=await db.WarehouseIngredientStocks.Where(x=>x.WarehouseId==warehouseId).ToListAsync(ct);var x=new StockCount{Id=Guid.NewGuid(),BranchId=branchId,WarehouseId=warehouseId,CountedByUserId=User(),CreatedAt=DateTime.UtcNow,Lines=stocks.Select(s=>new StockCountLine{IngredientId=s.IngredientId,SystemQuantity=s.CurrentQuantity,CountedQuantity=s.CurrentQuantity}).ToList()};db.StockCounts.Add(x);await db.SaveChangesAsync(ct);return await Get(x.Id,ct);}public async Task<StockCountDto>Get(Guid id,CancellationToken ct)=>await db.StockCounts.Where(x=>x.Id==id).Select(x=>new StockCountDto(x.Id,x.BranchId,x.WarehouseId,x.CreatedAt,x.Status,x.Lines.Select(l=>new StockCountLineDto(l.IngredientId,l.Ingredient.NameEn,l.SystemQuantity,l.CountedQuantity,l.VarianceQuantity)).ToList())).SingleAsync(ct);public async Task Save(Guid id,List<CountLineInput> input,CancellationToken ct){var x=await db.StockCounts.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new NotFoundException("Count not found.");if(x.Status!=StockCountStatuses.Draft)throw new ValidationException("Finalized count cannot be changed.");foreach(var line in x.Lines){var row=input.SingleOrDefault(i=>i.IngredientId==line.IngredientId)??throw new ValidationException("All count lines are required.");if(row.CountedQuantity<0)throw new ValidationException("Count cannot be negative.");line.CountedQuantity=row.CountedQuantity;line.VarianceQuantity=row.CountedQuantity-line.SystemQuantity;}await db.SaveChangesAsync(ct);}public async Task Finalize(Guid id,CancellationToken ct){var x=await db.StockCounts.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new NotFoundException("Count not found.");if(x.Status!=StockCountStatuses.Draft)throw new ValidationException("Count already finalized.");var reason=await db.InventoryTransactionReasons.SingleAsync(r=>r.Code=="INVENTORY_COUNT_ADJUSTMENT",ct);foreach(var line in x.Lines){var stock=await db.WarehouseIngredientStocks.SingleAsync(s=>s.WarehouseId==x.WarehouseId&&s.IngredientId==line.IngredientId,ct);line.VarianceQuantity=line.CountedQuantity-stock.CurrentQuantity;if(line.VarianceQuantity!=0)db.RestaurantInventoryTransactions.Add(new(){Id=Guid.NewGuid(),WarehouseId=x.WarehouseId,IngredientId=line.IngredientId,QuantityChange=line.VarianceQuantity,ReasonId=reason.Id,CreatedByUserId=User(),CreatedAt=DateTime.UtcNow});stock.CurrentQuantity=line.CountedQuantity;}x.Status=StockCountStatuses.Finalized;await db.SaveChangesAsync(ct);}Guid User()=>user.UserId??throw new ValidationException("Authenticated user required.");}
